CREATE OR REPLACE FUNCTION private.kandid_assign_election_academic_term()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'UPDATE' then
    if old.academic_term_id is not null and new.academic_term_id is distinct from old.academic_term_id then
      raise exception using errcode = '42501',
        message = 'An election academic term cannot be changed after it is recorded.';
    end if;
    return new;
  end if;

  if new.academic_term_id is null then
    raise exception using errcode = '22023',
      message = 'Choose the academic term this election belongs to.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.kandid_guard_frozen_electorate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.electorate_policy_version <> 1
       or new.electorate_frozen_at is not null
       or new.electorate_frozen_by is not null then
      raise exception using errcode = '42501', message = 'New elections must use the frozen-electorate policy and cannot be pre-locked.';
    end if;
    return new;
  end if;

  if old.electorate_frozen_at is not null and (
    new.electorate_frozen_at is distinct from old.electorate_frozen_at
    or new.electorate_frozen_by is distinct from old.electorate_frozen_by
    or new.electorate_policy_version is distinct from old.electorate_policy_version
    or new.organization_id is distinct from old.organization_id
    or new.academic_term_id is distinct from old.academic_term_id
    or new.start_date is distinct from old.start_date
    or new.end_date is distinct from old.end_date
  ) then
    raise exception using errcode = '42501', message = 'The locked election electorate, term, organization, and voting schedule are immutable.';
  end if;

  if new.electorate_policy_version is distinct from old.electorate_policy_version then
    raise exception using errcode = '42501', message = 'Election electorate policy cannot be changed.';
  end if;

  if old.electorate_frozen_at is null and new.electorate_frozen_at is not null then
    if pg_catalog.current_setting('kandid.lock_electorate', true) is distinct from 'on'
       or auth.uid() is null
       or not exists (
         select 1 from public.admin_users a
         where a.id = new.electorate_frozen_by
           and a.auth_user_id = auth.uid()
           and a.role = 'electoral_board'
           and a.status = 'active'
           and a.organization_id = new.organization_id
       ) then
      raise exception using errcode = '42501', message = 'Electorate lock must use the trusted Board operation.';
    end if;
  end if;

  if old.electorate_frozen_at is not null
     and lower(coalesce(old.status, '')) in ('closed', 'archived', 'done')
     and lower(coalesce(new.status, '')) = 'active' then
    raise exception using errcode = '42501', message = 'A closed election cannot be reopened.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.kandid_guard_result_release_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if pg_catalog.current_setting('kandid.allow_result_release_write', true)
       is distinct from 'on' then
    if tg_op = 'INSERT'
       and (new.results_released_at is not null or new.results_released_by is not null) then
      raise exception using errcode = '42501',
        message = 'Result finalization must use the trusted contract.';
    elsif tg_op = 'UPDATE'
       and (new.results_released_at is distinct from old.results_released_at
         or new.results_released_by is distinct from old.results_released_by) then
      raise exception using errcode = '42501',
        message = 'Result finalization must use the trusted contract.';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_election_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if new.campaign_end is null and new.start_date is not null then
    new.campaign_end := new.start_date;
  end if;

  if new.student_result_visibility is null then
    new.student_result_visibility :=
      case
        when coalesce(new.voting_results_visible, false) then 'realtime'
        else 'hidden'
      end;
  end if;

  new.voting_results_visible := (new.student_result_visibility = 'realtime');

  return new;
end;
$function$
